insert into problems (id,slug,title,category,summary,why_it_matters,definition,difficulty,status,skills,causes,claims,approaches,limitations,validation_criteria,created_at,updated_at) values ('p-water','low-cost-water-quality-monitoring','Improving low-cost water quality monitoring','water','Many communities cannot test their drinking water often enough to notice contamination early. Can open, low-cost sensing and simple lab methods close that gap reliably?','Drinking-water safety depends on regular testing. Where laboratory testing is expensive or far away, contamination can go unnoticed. Reliable low-cost monitoring would let communities, utilities and researchers detect problems sooner and target scarce lab capacity where it is most needed.','Design, calibrate and validate low-cost methods (sensors, test kits and data workflows) that measure selected drinking-water quality indicators with known, documented accuracy relative to reference laboratory methods, and that can be maintained by non-specialists.','intermediate','under_investigation',array['Embedded systems','Chemistry','Data analysis','Python','Field research']::text[],'[{"id":"c-water-1","title":"Cost of reference lab testing","description":"Accredited lab analysis can be expensive and slow to reach remote areas."},{"id":"c-water-2","title":"Sensor drift and calibration","description":"Inexpensive sensors can drift over time and need calibration routines that non-specialists can follow."},{"id":"c-water-3","title":"Fragmented data","description":"Results are often recorded in incompatible formats, which makes comparison and early warning difficult."}]'::jsonb,'[{"id":"cl-water-1","statement":"Drinking-water quality guidelines define indicators and management approaches for safe drinking water.","kind":"documented","sourceIds":["src-who-dwq"]},{"id":"cl-water-2","statement":"International monitoring programmes report on access to safely managed drinking-water services by country.","kind":"documented","sourceIds":["src-jmp"]},{"id":"cl-water-3","statement":"A multi-parameter open hardware probe with a monthly two-point calibration could track turbidity within a usable tolerance of a reference turbidimeter.","kind":"hypothesis","sourceIds":[]},{"id":"cl-water-4","statement":"Community-maintained sensors could serve as a triage layer that decides which samples are sent to a laboratory.","kind":"proposal","sourceIds":[]}]'::jsonb,'[{"title":"Field test kits","description":"Colorimetric and microbiological kits used by trained staff.","limitations":["Subjective reading of color scales","Consumables must be resupplied"]},{"title":"Open-hardware sensor probes","description":"Microcontroller-based probes measuring physical parameters such as turbidity, conductivity and temperature.","limitations":["Drift and fouling","Limited coverage of microbiological indicators"]},{"title":"Smartphone-based readers","description":"Using phone cameras to read test strips more consistently.","limitations":["Variation across phone models and lighting"]}]'::jsonb,array['Physical parameters cannot replace microbiological testing.','Accuracy claims depend on calibration against reference methods under local conditions.','Maintenance capacity varies between communities.']::text[],array['Paired measurements against a documented reference method, with raw data published.','Accuracy and bias reported with uncertainty, across at least two independent sites.','Calibration procedure reproduced by a contributor who did not design it.','Limitations and failure modes documented, including negative results.']::text[],'2026-03-10T09:00:00Z','2026-10-08T14:20:00Z') on conflict (id) do nothing;
insert into problem_sources values ('p-water','src-who-dwq') on conflict do nothing;
