insert into problems (id,slug,title,category,summary,why_it_matters,definition,difficulty,status,skills,causes,claims,approaches,limitations,validation_criteria,created_at,updated_at) values ('p-science','reproducible-scientific-experiments','Making scientific experiments more reproducible','science','Researchers report difficulty reproducing published results. Which practical tools and practices make computational and lab work easier to reproduce?','When results cannot be reproduced, effort is wasted and confidence in findings declines. Practical, low-friction reproducibility tools help every other problem on this platform, because validated progress depends on repeatable evidence.','Identify which concrete practices and tools (environment capture, data packaging, protocol templates) measurably increase the share of analyses an independent person can reproduce from published materials.','intermediate','evidence_submitted',array['Python','Technical writing','Statistics','TypeScript']::text[],'[{"id":"c-sci-1","title":"Missing computational environment","description":"Software versions and dependencies are often not recorded."},{"id":"c-sci-2","title":"Incomplete methods","description":"Protocols omit details needed to repeat an experiment."},{"id":"c-sci-3","title":"Inaccessible data","description":"Data is not shared, or shared without documentation."}]'::jsonb,'[{"id":"cl-sci-1","statement":"In a survey of researchers, many reported having tried and failed to reproduce another scientist''s experiment.","kind":"documented","sourceIds":["src-baker-2016"]},{"id":"cl-sci-2","statement":"A large replication effort in psychology reproduced fewer results than expected from the original studies.","kind":"documented","sourceIds":["src-osc-2015"]},{"id":"cl-sci-3","statement":"Reproducibility and replicability are distinct concepts with separate definitions.","kind":"documented","sourceIds":["src-nasem-2019"]},{"id":"cl-sci-4","statement":"A one-command environment capture tool would raise the share of notebooks that run unchanged on another machine.","kind":"hypothesis","sourceIds":[]}]'::jsonb,'[{"title":"Containers and lockfiles","description":"Capture software environments precisely.","limitations":["Learning curve","Large images"]},{"title":"FAIR data practices","description":"Make data findable, accessible, interoperable and reusable.","limitations":["Requires extra documentation effort"]},{"title":"Reporting checklists","description":"Journal or community checklists for methods reporting.","limitations":["Compliance is uneven"]}]'::jsonb,array['Some lab work is inherently variable.','Practices that add friction are often skipped.']::text[],array['Reproduction attempts performed by people not involved in the original work.','Clear definition of a successful reproduction stated before the attempt.','Failed reproduction attempts published alongside successful ones.']::text[],'2026-02-15T09:00:00Z','2026-10-10T09:30:00Z') on conflict (id) do nothing;
