insert into problems (id,slug,title,category,summary,why_it_matters,definition,difficulty,status,skills,causes,claims,approaches,limitations,validation_criteria,created_at,updated_at) values ('p-heat','urban-heat-resilience','Improving heat resilience in cities','climate','Extreme heat affects health, and some neighborhoods are hotter than others. How can cities find the most heat-exposed blocks and evaluate cooling measures locally?','Heat is a recognized health risk, and exposure is unequal within cities. Street-level data and transparent evaluation of cooling measures help residents and local governments prioritize interventions.','Build open methods to map street-level heat exposure and to evaluate cooling interventions (shade, surfaces, vegetation, cooling centers) with documented measurement protocols.','intermediate','under_investigation',array['GIS','Data analysis','Embedded systems','Community outreach']::text[],'[{"id":"c-heat-1","title":"Urban heat island effect","description":"Built surfaces absorb and re-emit heat, raising local temperatures."},{"id":"c-heat-2","title":"Sparse street-level data","description":"Official weather stations may not capture neighborhood variation."},{"id":"c-heat-3","title":"Unequal access to cooling","description":"Not all residents can reach shade or cooling centers."}]'::jsonb,'[{"id":"cl-heat-1","statement":"Extreme heat poses risks to human health.","kind":"documented","sourceIds":["src-who-heat"]},{"id":"cl-heat-2","statement":"Urban areas can experience higher temperatures than outlying areas (the heat island effect).","kind":"documented","sourceIds":["src-epa-heat-islands"]},{"id":"cl-heat-3","statement":"Volunteer-carried sensors could reveal block-level differences that fixed stations miss.","kind":"hypothesis","sourceIds":[]}]'::jsonb,'[{"title":"Satellite land-surface temperature","description":"Remote sensing of surface temperature.","limitations":["Surface temperature differs from air temperature people feel"]},{"title":"Community heat-mapping campaigns","description":"Coordinated mobile measurements.","limitations":["Snapshot in time","Sensor quality varies"]}]'::jsonb,array['Single-day campaigns may not represent typical conditions.','Health outcomes require careful epidemiological methods.']::text[],array['Sensor calibration documented against a reference.','Methods allow repetition on different days.','Any health claims reviewed by a qualified reviewer.']::text[],'2026-03-28T09:00:00Z','2026-10-05T12:00:00Z') on conflict (id) do nothing;
insert into problem_sources values ('p-heat','src-who-heat') on conflict do nothing;
