insert into problems (id,slug,title,category,summary,why_it_matters,definition,difficulty,status,skills,causes,claims,approaches,limitations,validation_criteria,created_at,updated_at) values ('p-edtech','accessible-educational-technology','Increasing accessibility of educational technology','accessibility','Learning platforms often fail students who use screen readers, captions, keyboards or low-bandwidth connections. Which barriers are most common, and which fixes help most?','When digital learning tools are inaccessible, disabled learners and learners with limited connectivity are excluded. Shared, open audits and fixes can benefit many institutions at once.','Measure common accessibility barriers in open educational tools against published standards, and develop and test open fixes with disabled learners.','introductory','under_investigation',array['Accessibility testing','TypeScript','UX research','Interface design']::text[],'[{"id":"c-edtech-1","title":"Accessibility treated as an afterthought","description":"Barriers are introduced early and expensive to fix later."},{"id":"c-edtech-2","title":"Limited testing with disabled users","description":"Automated checks miss many real barriers."}]'::jsonb,'[{"id":"cl-edtech-1","statement":"WCAG 2.2 defines testable success criteria for accessible web content.","kind":"documented","sourceIds":["src-wcag22"]},{"id":"cl-edtech-2","statement":"Universal Design for Learning provides guidelines for flexible learning design.","kind":"documented","sourceIds":["src-udl"]},{"id":"cl-edtech-3","statement":"Automated checkers catch only part of the barriers that disabled learners encounter.","kind":"proposal","sourceIds":[]}]'::jsonb,'[{"title":"Automated accessibility checkers","description":"Scan pages for detectable issues.","limitations":["Cannot judge many criteria"]},{"title":"Manual expert audits","description":"Specialists test against standards.","limitations":["Costly","May still miss lived-experience issues"]}]'::jsonb,array['Platforms change frequently, so audits age quickly.']::text[],array['Barriers mapped to specific WCAG success criteria.','Fixes tested with assistive technology users.','Audit method published so others can repeat it.']::text[],'2026-01-25T09:00:00Z','2026-10-11T08:00:00Z') on conflict (id) do nothing;
insert into problem_sources values ('p-edtech','src-wcag22') on conflict do nothing;
