insert into problems (id,slug,title,category,summary,why_it_matters,definition,difficulty,status,skills,causes,claims,approaches,limitations,validation_criteria,created_at,updated_at) values ('p-food','urban-food-waste-supply-chains','Reducing food waste in urban supply chains','food','Edible food is discarded at retail and distribution stages while nearby organizations struggle to source it. Where exactly is it lost, and which interventions measurably reduce it?','Food that is produced but not eaten wastes the land, water, energy and labor used to grow and move it. Better measurement and coordination in cities could redirect surplus to people and reduce environmental impact.','Identify the stages of urban food distribution where edible surplus is lost, and test interventions (forecasting, redistribution logistics, date-labeling practices) with measurable, reported outcomes.','intermediate','under_investigation',array['Supply chain','Data analysis','Policy analysis','Python']::text[],'[{"id":"c-food-1","title":"Inaccurate demand forecasts","description":"Over-ordering to avoid empty shelves can create surplus."},{"id":"c-food-2","title":"Short redistribution windows","description":"Perishable surplus must be moved quickly, which strains volunteer logistics."},{"id":"c-food-3","title":"Inconsistent measurement","description":"Different definitions of loss and waste make results hard to compare."}]'::jsonb,'[{"id":"cl-food-1","statement":"International reports distinguish food loss (earlier in the supply chain) from food waste (retail, food service and households).","kind":"documented","sourceIds":["src-fao-sofa","src-unep-fwi"]},{"id":"cl-food-2","statement":"Food waste occurs across households, food service and retail.","kind":"documented","sourceIds":["src-unep-fwi"]},{"id":"cl-food-3","statement":"Matching surplus pickups to recipient capacity in near-real time could reduce discarded perishables.","kind":"hypothesis","sourceIds":[]}]'::jsonb,'[{"title":"Food recovery networks","description":"Volunteer or nonprofit pickup of surplus from retailers.","limitations":["Depend on volunteer availability","Limited cold-chain capacity"]},{"title":"Dynamic markdowns","description":"Discounting products approaching their date.","limitations":["Effect varies by store and product category"]}]'::jsonb,array['Retail data is often proprietary.','Interventions may shift waste to other stages instead of reducing it.']::text[],array['Uses a stated, published definition of food loss and waste.','Reports baseline and post-intervention measurements with the same method.','Accounts for displacement to other supply-chain stages.']::text[],'2026-04-02T09:00:00Z','2026-09-29T11:00:00Z') on conflict (id) do nothing;
insert into problem_sources values ('p-food','src-unep-fwi') on conflict do nothing;
