insert into problems (id,slug,title,category,summary,why_it_matters,definition,difficulty,status,skills,causes,claims,approaches,limitations,validation_criteria,created_at,updated_at) values ('p-energy','small-building-energy-efficiency','Improving energy efficiency in small buildings','energy','Small homes, schools and shops rarely receive professional energy audits. Which low-cost measurements reliably identify the retrofits worth doing first?','Buildings are a major part of energy demand. Owners of small buildings often lack affordable, trustworthy guidance on where to start, so cost-effective improvements are delayed.','Develop and validate a low-cost assessment method that ranks retrofit options for small buildings, using measurements that owners or volunteers can collect, with documented accuracy against professional audits.','intermediate','proposed',array['Building science','Data analysis','Embedded systems','Python']::text[],'[{"id":"c-energy-1","title":"Audit cost","description":"Professional audits may cost more than owners of small buildings are willing to pay up front."},{"id":"c-energy-2","title":"Lack of baseline data","description":"Few small buildings have interval energy data or temperature logs."}]'::jsonb,'[{"id":"cl-energy-1","statement":"Buildings account for a substantial share of global energy use.","kind":"documented","sourceIds":["src-iea-buildings"]},{"id":"cl-energy-2","statement":"Energy benchmarking tools let owners compare their building''s energy use with similar buildings.","kind":"documented","sourceIds":["src-energystar-pm"]},{"id":"cl-energy-3","statement":"Two weeks of indoor/outdoor temperature logs plus utility bills may be enough to rank envelope improvements against HVAC upgrades.","kind":"hypothesis","sourceIds":[]}]'::jsonb,'[{"title":"Benchmarking against similar buildings","description":"Compare normalized energy use against peers.","limitations":["Does not identify specific measures"]},{"title":"Walk-through checklists","description":"Volunteer-led visual inspections.","limitations":["Quality depends on the inspector"]}]'::jsonb,array['Climate and occupancy differ widely.','Owner-collected data may be incomplete.']::text[],array['Rankings compared with professional audits on the same buildings.','Method documented so a new volunteer can repeat it.','Disagreements with professional audits reported, not only agreements.']::text[],'2026-05-11T09:00:00Z','2026-09-12T16:00:00Z') on conflict (id) do nothing;
insert into problem_sources values ('p-energy','src-iea-buildings') on conflict do nothing;
insert into problem_sources values ('p-energy','src-energystar-pm') on conflict do nothing;
insert into problems (id,slug,title,category,summary,why_it_matters,definition,difficulty,status,skills,causes,claims,approaches,limitations,validation_criteria,created_at,updated_at) values ('p-storage','energy-storage-off-grid-clinics','Reliable energy storage for off-grid health clinics','energy','Clinics without reliable electricity struggle to keep vaccines cold and equipment running. How can battery systems be sized, monitored and maintained for long, predictable lifetimes?','Health services depend on electricity for refrigeration, lighting and medical devices. Storage systems that fail early or are poorly sized leave clinics without power when it matters.','Develop open sizing guidance and low-cost monitoring for solar-plus-storage systems in off-grid clinics, validated against field data on battery health and outages.','advanced','proposed',array['Electrical engineering','Embedded systems','Data analysis']::text[],'[{"id":"c-storage-1","title":"Undersized systems","description":"Load estimates may omit equipment added after installation."},{"id":"c-storage-2","title":"No battery-health monitoring","description":"Degradation goes unnoticed until failure."}]'::jsonb,'[{"id":"cl-storage-1","statement":"Progress on access to electricity is tracked internationally as part of Sustainable Development Goal 7.","kind":"documented","sourceIds":["src-sdg7"]},{"id":"cl-storage-2","statement":"Simple state-of-health estimates from voltage and temperature logs could warn of battery failure weeks ahead.","kind":"hypothesis","sourceIds":[]}]'::jsonb,'[{"title":"Solar home system kits","description":"Packaged panels, batteries and controllers.","limitations":["Sized for households, not clinical loads"]}]'::jsonb,array['Field data is scarce and often proprietary.','Safety-critical: designs need qualified review.']::text[],array['Sizing guidance reviewed by a qualified electrical engineer.','Monitoring predictions compared against recorded failures.','Safety considerations documented.']::text[],'2026-07-01T09:00:00Z','2026-09-20T10:00:00Z') on conflict (id) do nothing;
