insert into research_questions values ('q-water-1','p-water','How closely can a low-cost turbidity sensor match a reference turbidimeter across realistic water conditions?','Turbidity is a common operational indicator. Knowing a low-cost sensor''s accuracy envelope decides whether it can be trusted for screening.','Turbidity measurement principles are well established, and reference instruments are standardized. The performance of specific low-cost designs under field conditions is less documented.',array['Effect of ambient light and bubbles','Drift rate between calibrations','Performance at very low turbidity']::text[],array['Paired bench tests using prepared standards','Field co-location with a reference instrument','Publish raw paired data and analysis notebooks']::text[],array['Embedded systems','Laboratory methods','Statistics']::text[],'under_investigation') on conflict (id) do nothing;
insert into research_questions values ('q-water-2','p-water','What calibration routine can non-specialists perform reliably with locally available materials?','A sensor that is only accurate when calibrated by experts will not stay accurate in community use.','Calibration with reference standards is standard practice in laboratories. Simplified procedures for community use are less studied.',array['Stability of low-cost calibration standards','How often calibration is needed','Error introduced by different operators']::text[],array['Usability study with first-time operators','Compare inter-operator variance','Iterate on illustrated instructions']::text[],array['UX research','Technical writing','Laboratory methods']::text[],'proposed') on conflict (id) do nothing;
insert into research_questions values ('q-water-3','p-water','What open data format lets community water readings be compared across sites and devices?','Without consistent metadata, results from different devices cannot be compared or aggregated for early warning.','General principles for findable, interoperable data exist. A lightweight schema tailored to community water monitoring has not been agreed here.',array['Minimum metadata needed for comparability','Handling of device calibration history']::text[],array['Review existing environmental data standards','Draft a JSON schema and validate it against sample records']::text[],array['Data analysis','TypeScript','Technical writing']::text[],'evidence_submitted') on conflict (id) do nothing;
insert into research_questions values ('q-sci-1','p-science','Which environment-capture approach do researchers actually adopt when given a choice?','A tool only helps if people use it.','Guidance recommends recording software versions and environments. Adoption barriers for specific tools are less documented.',array['Differences between disciplines','Effect of institutional support']::text[],array['Short structured interviews','Comparative usability test of three approaches']::text[],array['UX research','Python']::text[],'under_investigation') on conflict (id) do nothing;
insert into research_questions values ('q-sci-2','p-science','How often do public analysis notebooks run unchanged in a clean environment?','A baseline is needed before claiming any tool improves reproducibility.','Concerns about notebook reproducibility are widely discussed; a baseline for the notebooks linked from this platform does not yet exist.',array['Sampling bias','Definition of ''runs unchanged''']::text[],array['Pre-register the definition of success','Automated re-execution in containers']::text[],array['Python','Statistics']::text[],'evidence_submitted') on conflict (id) do nothing;
insert into research_questions values ('q-sci-3','p-science','What minimal protocol template captures the details needed to repeat a bench experiment?','Missing details are a common reason lab experiments cannot be repeated.','Reporting checklists exist in several fields; a minimal cross-disciplinary template is not agreed.',array['Template length versus completion rate']::text[],array['Compare existing checklists','Pilot with platform experiments']::text[],array['Laboratory methods','Technical writing']::text[],'proposed') on conflict (id) do nothing;
insert into research_questions values ('q-heat-1','p-heat','How should mobile temperature readings be corrected for time of day when building a heat map?','Readings taken at different times are not directly comparable.','Time-detrending is used in mobile measurement campaigns; the best approach for small volunteer datasets is unclear.',array['Effect of route order','Required reference station density']::text[],array['Compare detrending methods on open datasets','Simulate with synthetic routes']::text[],array['Statistics','GIS','Python']::text[],'under_investigation') on conflict (id) do nothing;
insert into research_questions values ('q-heat-2','p-heat','Which residents are least able to reach cooling centers, and why?','Cooling centers only help people who can reach and use them.','Access depends on distance, opening hours, transport and awareness; local data is often missing.',array['Data on mobility limitations','Awareness of services']::text[],array['Accessibility analysis using open transit data','Community interviews']::text[],array['GIS','Community outreach','Field research']::text[],'proposed') on conflict (id) do nothing;
insert into research_questions values ('q-edtech-1','p-edtech','Which WCAG failures occur most often in open-source learning management systems?','Knowing the most frequent failures lets contributors fix what affects the most learners.','Standards define success criteria; a shared, repeatable audit of open-source learning platforms is not available here yet.',array['Variation between versions and themes']::text[],array['Combine automated scans with manual keyboard and screen-reader testing','Publish an audit protocol']::text[],array['Accessibility testing']::text[],'under_investigation') on conflict (id) do nothing;
insert into research_questions values ('q-edtech-2','p-edtech','What lightweight page design keeps course materials usable on slow connections?','Heavy pages exclude learners with limited bandwidth or older devices.','Web performance techniques are well known; their application to course content templates is uneven.',array['Which media formats learners actually use']::text[],array['Measure page weight of sample courses','Prototype a text-first template']::text[],array['TypeScript','Interface design']::text[],'proposed') on conflict (id) do nothing;
insert into research_questions values ('q-food-1','p-food','Which measurement method gives comparable food-waste figures across small retailers?','Without a shared method, no intervention can be compared or validated.','International reports describe measurement approaches at national level. Practical methods for small independent retailers are less documented.',array['Accuracy of self-reported weights','Seasonal variation']::text[],array['Review published measurement guidance','Pilot a simple weighing log with volunteer stores']::text[],array['Data analysis','Field research']::text[],'under_investigation') on conflict (id) do nothing;
insert into research_questions values ('q-food-2','p-food','Can open routing tools shorten the time between surplus notice and pickup for food recovery groups?','Perishables lose value quickly; faster pickups could increase how much surplus is usable.','Vehicle routing is a well-studied optimization problem. Its use by small volunteer networks is less studied.',array['Volunteer acceptance of suggested routes','Data availability on recipient capacity']::text[],array['Prototype with open routing libraries','Simulate with anonymized historical pickup logs']::text[],array['Python','Supply chain','GIS']::text[],'proposed') on conflict (id) do nothing;
insert into research_questions values ('q-food-3','p-food','How do date-label practices influence discard decisions at retail?','Confusion between quality and safety dates may cause edible food to be discarded.','Several reports discuss date labeling as a factor in waste. Local retail practices vary.',array['Regional regulatory differences']::text[],array['Policy review across jurisdictions','Interviews with store managers']::text[],array['Policy analysis','Literature review']::text[],'proposed') on conflict (id) do nothing;
insert into research_questions values ('q-energy-1','p-energy','What is the minimum dataset needed to estimate a small building''s heat-loss coefficient?','A simple heat-loss estimate could separate envelope problems from equipment problems.','Methods for estimating heat-loss coefficients from measured data exist in building science literature; their reliability with sparse owner-collected data is less clear.',array['Effect of occupant behavior','Required logging duration']::text[],array['Literature review of in-situ measurement methods','Test on public building datasets']::text[],array['Building science','Statistics','Literature review']::text[],'proposed') on conflict (id) do nothing;
insert into research_questions values ('q-energy-2','p-energy','Can a low-cost temperature logger kit be assembled and deployed by volunteers?','Measurement must be cheap and simple to scale.','Low-cost temperature sensors are widely available; their placement and calibration in buildings require care.',array['Sensor placement errors','Battery life']::text[],array['Build a reference kit','Write deployment instructions and test them']::text[],array['Embedded systems','Technical writing']::text[],'proposed') on conflict (id) do nothing;
insert into research_questions values ('q-storage-1','p-storage','What load profile should be assumed when sizing storage for a small rural clinic?','Sizing depends on realistic loads, including vaccine refrigeration.','Equipment specifications are available; measured clinic load profiles are rarely published openly.',array['Seasonal variation','Equipment added over time']::text[],array['Collect equipment inventories','Build a load-profile calculator with explicit assumptions']::text[],array['Electrical engineering','Data analysis']::text[],'proposed') on conflict (id) do nothing;
insert into research_questions values ('q-storage-2','p-storage','Can low-cost voltage and temperature logging predict battery degradation early enough to act?','Early warning allows planned replacement instead of sudden outages.','Battery state-of-health estimation is an active research field; low-cost field implementations are less documented.',array['Battery chemistry differences','Data logging reliability']::text[],array['Review estimation methods','Test on open battery-cycling datasets']::text[],array['Data analysis','Embedded systems','Machine learning']::text[],'proposed') on conflict (id) do nothing;
insert into hypotheses values ('h-water-1','q-water-1','A shielded optical turbidity probe with two-point monthly calibration stays within a predefined tolerance of a reference turbidimeter.','under_investigation') on conflict (id) do nothing;
insert into hypotheses values ('h-water-2','q-water-2','Illustrated step-by-step calibration cards reduce inter-operator variance compared with text-only instructions.','proposed') on conflict (id) do nothing;
