insert into hypotheses values ('h-sci-2','q-sci-1','Researchers prefer lockfile-based capture over containers for small analyses.','inconclusive') on conflict (id) do nothing;
insert into hypotheses values ('h-heat-1','q-heat-1','Linear detrending against a fixed reference station is adequate for routes under two hours.','under_investigation') on conflict (id) do nothing;
insert into hypotheses values ('h-edtech-1','q-edtech-1','Keyboard focus and form-labeling failures are among the most frequent barriers in course pages.','under_investigation') on conflict (id) do nothing;
insert into hypotheses values ('h-food-1','q-food-2','Route suggestions that account for recipient opening hours reduce average pickup delay for perishable surplus.','proposed') on conflict (id) do nothing;
