insert into hypotheses values ('h-storage-1','q-storage-2','Voltage-sag patterns under a known load correlate with remaining capacity in lead-acid and lithium iron phosphate batteries.','proposed') on conflict (id) do nothing;
insert into experiments values ('e-water-1','h-water-1','Bench comparison with prepared turbidity standards','Measure a dilution series of standards with three probe units and a reference instrument; repeat weekly for six weeks to estimate drift.','under_investigation') on conflict (id) do nothing;
insert into experiments values ('e-sci-1','h-sci-1','Re-execution of sampled public notebooks','Re-run a pre-registered sample of notebooks with and without pinned dependencies in clean containers.','evidence_submitted') on conflict (id) do nothing;
insert into experiments values ('e-sci-2','h-sci-2','Preference test with researchers','Ask participants to capture an environment with two tools and record completion and preference.','inconclusive') on conflict (id) do nothing;
