insert into solutions values ('s-water-1','p-water','Open sensor as lab-triage layer','Use community sensors to flag anomalies and prioritize which samples go to an accredited laboratory.','proposed',array['q-water-1','q-water-3']::text[]) on conflict (id) do nothing;
insert into solutions values ('s-sci-1','p-science','Reproducibility starter kit','Template repository with lockfile, data README and protocol template, used by every UNsolved experiment.','under_investigation',array['q-sci-1','q-sci-2','q-sci-3']::text[]) on conflict (id) do nothing;
insert into solutions values ('s-heat-1','p-heat','Open neighborhood heat-mapping toolkit','Sensor build guide, route planner and processing pipeline with documented uncertainty.','proposed',array['q-heat-1']::text[]) on conflict (id) do nothing;
insert into solutions values ('s-edtech-1','p-edtech','Open accessibility patch set','Upstream fixes for the most frequent barriers, tested with assistive-technology users.','proposed',array['q-edtech-1']::text[]) on conflict (id) do nothing;
insert into solutions values ('s-food-1','p-food','Open surplus-matching service','A lightweight service that matches surplus notices to nearby recipients with capacity.','proposed',array['q-food-2']::text[]) on conflict (id) do nothing;
insert into solutions values ('s-energy-1','p-energy','Volunteer energy check kit','Open logger kit plus analysis notebook that produces a ranked list of measures with stated uncertainty.','proposed',array['q-energy-1','q-energy-2']::text[]) on conflict (id) do nothing;
insert into solutions values ('s-storage-1','p-storage','Open clinic load calculator','A calculator with explicit, editable assumptions and safety notes.','proposed',array['q-storage-1']::text[]) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-water-1a','p-water','q-water-1','Write a bench-test protocol for turbidity sensor comparison','Define a repeatable procedure for comparing low-cost probes against a reference instrument.','Draft a protocol covering sample preparation, number of replicates, ambient-light control and data recording. Reference established measurement guidance where possible and mark any assumptions.','A protocol document (Markdown) with a data-recording template.',array['Laboratory methods','Technical writing']::text[],'intermediate','6–10 hours',array['Lists equipment and materials','Specifies replicates and acceptance tolerance','Includes a CSV template for paired readings','Cites the guidance it relies on']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-water-1b','p-water','q-water-1','Analysis notebook for paired sensor readings','Provide a reusable notebook that computes bias, agreement and drift from paired readings.','Build a Python notebook that ingests the CSV template, produces Bland–Altman style agreement plots and summary statistics, and documents assumptions. Use synthetic data for testing and label it as such.','Notebook plus a short README and synthetic example data.',array['Python','Statistics','Data analysis']::text[],'intermediate','8–12 hours',array['Runs end-to-end on the synthetic dataset','Reports uncertainty, not only point estimates','Synthetic data is clearly labeled']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-water-2a','p-water','q-water-2','Design an illustrated calibration card','Create a one-page visual guide for a two-point calibration routine.','Design a printable card that a first-time operator can follow without prior training. Prioritize clear sequencing and plain language; prepare it for translation.','Editable source file and a print-ready PDF.',array['Interface design','Technical writing']::text[],'introductory','4–6 hours',array['Fits on one printed page','Uses plain language','Text kept separate from graphics for translation']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-water-2b','p-water','q-water-2','Plan a small usability study of calibration instructions','Define how to measure whether non-specialists can calibrate correctly.','Write a study plan with participant criteria, tasks, consent considerations and metrics for operator error.','Study plan document with consent template.',array['UX research','Field research']::text[],'intermediate','5–8 hours',array['Defines measurable outcomes','Addresses informed consent','Describes how results will be published, including null results']::text[],'blocked','Waits for the calibration card draft (Design an illustrated calibration card).') on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-water-3a','p-water','q-water-3','Draft a JSON schema for community water readings','Propose a minimal schema covering location, device, calibration and measurement metadata.','Review related environmental data conventions and propose a JSON Schema with examples. Explain each required field.','JSON Schema, three valid example records and rationale document.',array['TypeScript','Data analysis','Technical writing']::text[],'introductory','4–8 hours',array['Schema validates the example records','Includes device calibration history','Rationale explains each required field']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-water-3b','p-water','q-water-3','Build a CSV-to-schema converter','Let field teams convert spreadsheet records into the shared schema.','Write a small command-line tool or web form that converts CSV exports into schema-valid JSON and reports errors in plain language.','Open-source tool with tests.',array['TypeScript','Python']::text[],'introductory','6–10 hours',array['Rejects invalid rows with a readable message','Includes automated tests']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-sci-1a','p-science','q-sci-1','Interview guide for environment-capture adoption','Prepare a short interview guide on how researchers record software environments.','Draft neutral, non-leading questions and a consent script. Keep interviews under 20 minutes.','Interview guide and consent script.',array['UX research']::text[],'introductory','3–5 hours',array['Questions are non-leading','Includes consent script']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-sci-2a','p-science','q-sci-2','Automated notebook re-execution harness','Re-run notebooks in clean containers and record outcomes.','Build a harness that fetches notebooks, runs them in isolated containers with a timeout and records success or the failure category. Never execute untrusted code outside isolated sandboxes.','Open-source harness with documentation.',array['Python']::text[],'advanced','15–25 hours',array['Runs in isolated containers only','Categorizes failures','Outputs a machine-readable report']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-sci-2b','p-science','q-sci-2','Pre-register the definition of a successful re-run','Fix the success criteria before results are seen.','Write and timestamp a short pre-registration describing sampling, success definition and analysis plan.','Pre-registration document.',array['Statistics','Technical writing']::text[],'intermediate','3–4 hours',array['Timestamped before analysis','Defines success unambiguously']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-sci-3a','p-science','q-sci-3','Compare existing reporting checklists','Find overlap between methods-reporting checklists.','Pick three published checklists, map their items and identify a common core.','Mapping table and proposed minimal template.',array['Literature review','Laboratory methods']::text[],'intermediate','6–8 hours',array['Cites each checklist','Explains every exclusion']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-heat-1a','p-heat','q-heat-1','Implement three time-detrending methods','Make detrending approaches comparable in one library.','Implement the methods in Python with tests and a notebook comparing them on synthetic data.','Python module, tests and comparison notebook.',array['Python','Statistics']::text[],'intermediate','8–14 hours',array['Unit tests for each method','Synthetic data labeled','Documents assumptions']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-heat-1b','p-heat','q-heat-1','Find open mobile heat-measurement datasets','Catalogue datasets the methods can be tested on.','Search for openly licensed datasets from mobile temperature campaigns and record their license, format and metadata quality.','Dataset catalogue table.',array['Data analysis','Literature review']::text[],'introductory','3–6 hours',array['Records license for each dataset','Only openly licensed data included']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-heat-2a','p-heat','q-heat-2','Travel-time analysis to cooling centers','Estimate walking and transit travel times to cooling centers.','Use open street and transit data to compute travel times for a sample city, and document data gaps.','Reproducible notebook and map.',array['GIS','Python']::text[],'intermediate','10–16 hours',array['Uses only open data','Documents data gaps and assumptions']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-edtech-1a','p-edtech','q-edtech-1','Write a repeatable accessibility audit protocol','Define steps so different auditors reach comparable results.','Combine automated checks with manual keyboard and screen-reader steps, mapped to WCAG 2.2 criteria.','Audit protocol with a results template.',array['Accessibility testing','Technical writing']::text[],'intermediate','6–10 hours',array['Every step maps to a success criterion','Template records evidence for each finding']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-edtech-1b','p-edtech','q-edtech-1','Keyboard-only walkthrough of a course page','Record every keyboard barrier on a sample page.','Using only a keyboard, complete a set of learner tasks and record each place where focus is lost or a control is unreachable. Great first contribution.','Filled-in results template with screenshots.',array['Accessibility testing']::text[],'introductory','2–3 hours',array['Uses the published protocol','Includes steps to reproduce each barrier']::text[],'open',null) on conflict (id) do nothing;
insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-edtech-1c','p-edtech','q-edtech-1','Translate the audit protocol into Spanish','Let more auditors use the protocol.','Translate the protocol and template, keeping WCAG terms consistent with official translations where they exist.','Translated protocol.',array['Translation','Accessibility testing']::text[],'introductory','3–5 hours',array['Terminology consistent','Reviewed by a second speaker']::text[],'open',null) on conflict (id) do nothing;
