insert into tasks (id,problem_id,question_id,title,objective,description,deliverable,skills,difficulty,effort,acceptance_criteria,status,blocked_reason) values ('t-food-1a','p-food','q-food-1','Summarize published food-waste measurement methods','Compare measurement approaches described in public reports.','Read the linked reports and summarize how each defines and measures waste, noting what would be practical for small retailers. Quote and cite; do not extrapolate figures.','A literature summary with a comparison table and citations.',array['Literature review','Technical writing']::text[],'introductory','5–8 hours',array['Every claim cites a source','Includes a comparison table','Lists open questions']::text[],'open',null) on conflict (id) do nothing;
